const input=$input.first().json,raw=input.candidates?.[0]?.content?.parts?.[0]?.text||'{}';
let cl;try{cl=JSON.parse(raw);}catch(e){cl={topic:'OTHER',urgency:'normal',summary:(input._q||'').slice(0,20),tags:[],question_type:'other',preliminary_answer:'需要更多上下文才能准确解答',reply_hint:'感谢你的提问！'};}
const rm={AI_LLM:{label:'🤖 AI & LLM',color:'purple',res:[{t:'Google AI Studio — 免费体验 Gemini API',u:'https://aistudio.google.com/'},{t:'Gemini API 官方文档',u:'https://ai.google.dev/gemini-api/docs'},{t:'Vertex AI 快速入门 Codelab',u:'https://codelabs.developers.google.com/codelabs/gemini-vertex-ai-tour'}]},CLOUD_GCP:{label:'☁️ Cloud & GCP',color:'blue',res:[{t:'Google Cloud Skills Boost — 免费学习路径',u:'https://cloudskillsboost.google/'},{t:'Cloud Run 官方文档',u:'https://cloud.google.com/run/docs'},{t:'GCP 架构中心 — 最佳实践参考',u:'https://cloud.google.com/architecture'}]},MOBILE_FLUTTER:{label:'📱 Mobile & Flutter',color:'turquoise',res:[{t:'Flutter 官方文档',u:'https://docs.flutter.dev/'},{t:'Firebase 快速入门指南',u:'https://firebase.google.com/docs/guides'},{t:'Flutter Codelabs 合集',u:'https://docs.flutter.dev/codelabs'}]},WEB_FRONTEND:{label:'🌐 Web & 前端',color:'green',res:[{t:'web.dev 官方学习路径',u:'https://web.dev/learn'},{t:'Chrome for Developers',u:'https://developer.chrome.com/'},{t:'PageSpeed Insights — 性能测速工具',u:'https://pagespeed.web.dev/'}]},OTHER:{label:'💬 综合话题',color:'grey',res:[{t:'Google Codelabs — 动手实验合集',u:'https://codelabs.developers.google.com/'},{t:'GDG 社区主页',u:'https://developers.google.com/community/gdg'},{t:'Google Developers 官方博客',u:'https://developers.googleblog.com/'}]}};
const td=rm[cl.topic]||rm.OTHER,name=input._name||'朋友',q=input._q||'',email=input._email||'';
const urgMap={high:'⚠️ 紧急',normal:'🔵 普通',low:'🔘 低'};
const qtMap={'how-to':'🔧 操作指南',debug:'🐛 问题排查',concept:'💡 概念理解',opinion:'💬 观点讨论',other:'❓ 其他'};
const tags=Array.isArray(cl.tags)?cl.tags.map(t=>'#'+t).join('  '):''
const qtLabel=qtMap[cl.question_type]||'❓ 其他';
const pa=cl.preliminary_answer||'暂无初步解答';
const feishuCard=JSON.stringify({msg_type:'interactive',card:{header:{title:{content:'🔔 新提问 · '+td.label,tag:'plain_text'},template:td.color},elements:[{tag:'div',fields:[{is_short:true,text:{tag:'lark_md',content:'**提问者**\n'+name}},{is_short:true,text:{tag:'lark_md',content:'**紧迫度**\n'+(urgMap[cl.urgency]||'🔵 普通')}},{is_short:true,text:{tag:'lark_md',content:'**类型**\n'+qtLabel}}]},{tag:'div',text:{tag:'lark_md',content:'**❓ 问题内容**\n'+q}},{tag:'hr'},{tag:'div',text:{tag:'lark_md',content:'**🤖 AI 初步解答**\n'+pa}},{tag:'hr'},{tag:'note',elements:[{tag:'plain_text',content:'📝 '+cl.summary+(tags?'  |  🏷️ '+tags:'')+'  ·  GDG 智能提问墙 n8n × Gemini'}]}]}});
const rl=td.res.map(r=>`<li><a href="${r.u}" style="color:#1a73e8;text-decoration:none;">${r.t}</a></li>`).join('');
const emailHtml=`<!DOCTYPE html><html><head><meta charset='utf-8'></head><body style='font-family:-apple-system,BlinkMacSystemFont,Segoe UI,Roboto,sans-serif;background:#f5f5f5;margin:0;padding:32px 16px;'><div style='max-width:600px;margin:0 auto;background:#fff;border-radius:12px;padding:32px;box-shadow:0 2px 8px rgba(0,0,0,.06);'><h2 style='color:#1a1a1a;margin-top:0;'>Hi ${name}，</h2><p style='color:#444;font-size:16px;line-height:1.6;'>感谢你在 <strong>GDG 活动现场</strong>提问！🎉 你的问题已归类到 <strong>${td.label}</strong>，Gemini 已为你生成了初步解答：</p><div style='background:#f0f4ff;border-left:4px solid #4f46e5;padding:16px;margin:20px 0;border-radius:4px;'><p style='margin:0 0 8px;font-weight:600;color:#1a1a1a;'>🤖 AI 初步解答</p><p style='margin:0;color:#444;font-size:15px;line-height:1.7;'>${pa}</p></div><div style='background:#f8fafc;border-left:4px solid #1a73e8;padding:16px;margin:20px 0;border-radius:4px;'><p style='margin:0 0 8px;font-weight:600;color:#1a1a1a;'>📦 精选学习资料</p><ul style='margin:0;padding-left:20px;line-height:2;'>${rl}</ul></div><p style='font-style:italic;background:#fafafa;padding:12px 16px;border-radius:8px;color:#555;'>「${cl.reply_hint}」</p><p style='color:#444;font-size:16px;line-height:1.6;'>欢迎加入 GDG 社区，与更多开发者保持连接！</p><hr style='border:none;border-top:1px solid #e4e4e7;margin:20px 0 12px;'><p style='color:#999;font-size:13px;margin:0;'>Best regards,<br>GDG 活动团队 · Powered by n8n × Gemini</p></div></body></html>`;
return [{json:{...input,topic:cl.topic,urgency:cl.urgency,summary:cl.summary,tags:cl.tags,question_type:cl.question_type,preliminary_answer:pa,reply_hint:cl.reply_hint,topicLabel:td.label,feishuCard,emailHtml,hasEmail:!!(email&&email.trim())}}];
